"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["87616"],{25687(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>c,frontMatter:()=>r,contentTitle:()=>i,toc:()=>h,assets:()=>l});var o=JSON.parse('{"id":"qiangguo/maopoemflaws5","title":"","description":"Girl Who Likes Mathematics","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/qiangguo/maopoemflaws5.md","sourceDirName":"qiangguo","slug":"/qiangguo/maopoemflaws5","permalink":"/en/qiangguo/maopoemflaws5","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"maopoemflaws5","title":"","hide_table_of_contents":true,"sidebar_label":"An objective evaluation of flaws in Mao Zedong\'s poetry (Part 5)"},"sidebar":"qiangguoSidebar","previous":{"title":"An objective evaluation of flaws in Mao Zedong\'s poetry (Part 4)","permalink":"/en/qiangguo/maopoemflaws4"},"next":{"title":"Why a simple critique of Mao Zedong\'s poetry provoked such fury from the left","permalink":"/en/qiangguo/maopoemcommenteffects"}}'),s=t(74848),a=t(28453);let r={id:"maopoemflaws5",title:"",hide_table_of_contents:!0,sidebar_label:"An objective evaluation of flaws in Mao Zedong's poetry (Part 5)"},i="An Objective Evaluation of the Flaws in Mao Zedong's Poetry (Part Five)",l={},h=[];function d(e){let n={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"an-objective-evaluation-of-the-flaws-in-mao-zedongs-poetry-part-five",children:"An Objective Evaluation of the Flaws in Mao Zedong's Poetry (Part Five)"})}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:"Girl Who Likes Mathematics"}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:"Below, let us analyze one of Mao Zedong's seven-character regulated verses in detail:"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:["The Red Army fears not the trials of a long campaign; ten thousand rivers and thousand mountains are taken as nothing.",(0,s.jsx)("br",{}),"\nThe Five Ridges wind and roll like slender waves; vast Wumeng strides by like a lump of mud.",(0,s.jsx)("br",{}),"\nGold Sand waters slap warm cloud-cliffs; Dadu Bridge lies across with iron chains cold.",(0,s.jsx)("br",{}),"\nBetter still, Minshan's thousand miles of snow; after the three armies pass, all faces break into smiles."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'First, the character "han" (cold) falls outside the prescribed rhyme group. In strict seven-character regulated verse, this is impermissible. Additionally, the characters "shui" (water), "shan" (mountain), and "qian" (thousand) all appear as repeated characters across alternating lines, which is equally impermissible in seven-character regulated verse. The two middle couplets are very loosely paralleled -- barely passable at best. More importantly, the imagery of these two couplets is extremely repetitive. Of course, as a news chronicle this is no problem. As poetry, however, it seems somewhat off. Some may invoke extra-poetic justifications, which is all fine, but one can only say this cannot be considered a good seven-character regulated verse. As a song lyric it might pass, and as a rhymed historical record there is certainly no issue, but these have nothing to do with poetry itself.'}),"\n",(0,s.jsx)(n.p,{children:"For comparison, this next poem, also about a historical event, is considerably better:"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:["On Purple Mountain wind and rain rise in yellow dusk; a million mighty troops cross the Great River.",(0,s.jsx)("br",{}),"\nTiger crouched and dragon coiled, today surpasses yesterday; heaven and earth overturned, solemn and impassioned.",(0,s.jsx)("br",{}),"\nWe should use our remaining courage to chase the beaten foe; never sell reputation cheap by imitating the Hegemon King.",(0,s.jsx)("br",{}),"\nIf heaven had feelings, heaven too would age; the righteous way in the human world is the change of ages."]}),"\n"]}),"\n",(0,s.jsx)(n.p,{children:'Although the character "jiang" (river) also falls outside the prescribed rhyme group, the repeated-character problem is gone. The two middle couplets are much better paralleled than in the previous poem, and there is no longer the plodding repetition between them -- there is flow. The best parts of this poem are the opening and the closing. Although it borrows a line from Li He, the borrowing is appropriate. And there is a hint of lingering resonance rare in Mao Zedong\'s seven-character regulated verse. Combined with the above, this counts as the best among Mao Zedong\'s seven-character regulated verses. Frankly, what makes the whole poem work is precisely the borrowed line from Li He -- "If heaven had feelings, heaven too would age" -- which tempers what might otherwise have devolved into coarseness. So this borrowing is rather apt.'}),"\n",(0,s.jsx)(n.p,{children:"Below are three more of Mao Zedong's better seven-character regulated verses:"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:["Drinking tea by the Guangdong sea, I could not forget; seeking lines in Yuzhou as leaves turn yellow.",(0,s.jsx)("br",{}),"\nAfter thirty-one years I return to my old country; in falling-flower season I read splendid chapters.",(0,s.jsx)("br",{}),"\nToo much grievance can break the gut, beware; landscapes and affairs should always be viewed with broad eyes.",(0,s.jsx)("br",{}),'\nDo not say Kunming Pool is shallow; watching fish there surpasses the Fuchun River. (Minor regret: "jiang" falls outside the rhyme group)']}),"\n"]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:["One mountain shoots up by the great river; leaping up through four hundred lush turns.",(0,s.jsx)("br",{}),"\nWith cold eyes facing the ocean, I look on the world; warm wind blows rain and scatters it over river and sky.",(0,s.jsx)("br",{}),"\nClouds stretch across nine waterways, floating Yellow Crane; waves descend through the Three Wu, raising white mist.",(0,s.jsx)("br",{}),"\nWhere has Magistrate Tao gone, no one knows; in Peach Blossom Spring, can fields still be tilled? (Could the closing couplet have been better?)"]}),"\n"]}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsxs)(n.p,{children:["Over Nine-Doubt Mountain white clouds fly; imperial daughters ride the wind down emerald slopes.",(0,s.jsx)("br",{}),"\nOne spray of mottled bamboo, a thousand drops of tears; ten thousand red clouds, a hundred layered robes.",(0,s.jsx)("br",{}),"\nDongting's waves surge like sky-linked snow; on Long Isle people's songs move earth like poetry.",(0,s.jsx)("br",{}),'\nI wish by this to dream vast and boundless; in the Hibiscus Land all is morning radiance. (Minor regret: "shi" (poetry) falls outside the rhyme group)']}),"\n"]})]})}function c(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,n,t){t.d(n,{R:()=>r,x:()=>i});var o=t(96540);let s={},a=o.createContext(s);function r(e){let n=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),o.createElement(a.Provider,{value:n},e.children)}}}]);